window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1454ac5560939916"]={"versions": [{"id": "FIG-1454ac5560939916", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenformat- und Speicherlayout-Diagramm im Kontext des AUTOSAR Diagnostic Event Managers (Dem). Das Diagramm visualisiert die lineare Bytestruktur des Puffers (<code>DestBuffer</code>), der bei der Abfrage von erweiterten Diagnosedaten über die Schnittstelle <code>Dem_DcmGetExtendedDataRecordByDTC</code> an das Diagnostic Communication Manager (Dcm) Modul übergeben wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>requested extended data record</strong>: Übergeordneter Datenblock, der durch einen Doppelpfeil über die gesamte Bytefolge <code>Byte 0..n</code> aufgespannt wird.\n</li><li><strong>Data</strong>: Zusammenfassender Pufferbereich (grau hinterlegtes Feld), der die Rohdaten des angeforderten Extended Data Records repräsentiert.\n</li><li><strong>Byte 0..n</strong>: Indizierung der Byterange des Puffers.\n</li><li><strong>Data element #1 bis Data element #N</strong>: Sequenzielle logische Datenelemente innerhalb des Datenteils, getrennt durch Auslassungspunkte (<code>...</code>) zur Kennzeichnung variabler Elementanzahlen.\n</li><li>Gestrichelte Projektionslinien verdeutlichen die Detailauflösung des übergeordneten <code>Data</code>-Blocks in die einzelnen Datenelemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Aufruf von <code>Dem_DcmGetExtendedDataRecordByDTC</code> serialisiert der Dem die für ein bestimmtes DTC gespeicherten Nutzdaten des angeforderten Datensatzes in den bereitgestellten Zielpuffer. Die Datenelemente (<code>Data element #1</code> bis <code>#N</code>) werden ohne vorangestellte Record-Nummer oder zusätzliche Header direkt sequenziell ab Byte 0 in den Puffer kopiert. Ist der Record gültig, aber nicht gespeichert, bleibt der Puffer leer (Größe 0).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Diagramm gemäß SWS_Dem_00075 das exakte Pufferformat für die Übergabe an das Dcm: Der Puffer enthält ausschließlich die reinen Nutzdaten (<code>Data element #1..#N</code>) des angeforderten Datensatzes. Dies steht im normativen Gegensatz zu Funktionen wie <code>Dem_DcmGetSizeOfExtendedDataRecordByDTC</code> (SWS_Dem_00076), bei denen Headerinformationen (wie die Record-Nummer) mitgezählt werden. Entwickler müssen sicherstellen, dass der Puffer mindestens die Gesamtlänge der summierten Nutzdatenelemente aufnehmen kann.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7a454033a5910788", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Datenformat- und Speicherlayout-Diagramm im Kontext des AUTOSAR Diagnostic Event Managers (Dem). Das Diagramm visualisiert die lineare Bytestruktur des Puffers (<code>DestBuffer</code>), der bei der Abfrage von erweiterten Diagnosedaten über die Schnittstelle <code>Dem_DcmGetExtendedDataRecordByDTC</code> an das Diagnostic Communication Manager (Dcm) Modul übergeben wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>requested extended data record</strong>: Übergeordneter Datenblock, der durch einen Doppelpfeil über die gesamte Bytefolge <code>Byte 0..n</code> aufgespannt wird.\n</li><li><strong>Data</strong>: Zusammenfassender Pufferbereich (grau hinterlegtes Feld), der die Rohdaten des angeforderten Extended Data Records repräsentiert.\n</li><li><strong>Byte 0..n</strong>: Indizierung der Byterange des Puffers.\n</li><li><strong>Data element #1 bis Data element #N</strong>: Sequenzielle logische Datenelemente innerhalb des Datenteils, getrennt durch Auslassungspunkte (<code>...</code>) zur Kennzeichnung variabler Elementanzahlen.\n</li><li>Gestrichelte Projektionslinien verdeutlichen die Detailauflösung des übergeordneten <code>Data</code>-Blocks in die einzelnen Datenelemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Aufruf von <code>Dem_DcmGetExtendedDataRecordByDTC</code> serialisiert der Dem die für ein bestimmtes DTC gespeicherten Nutzdaten des angeforderten Datensatzes in den bereitgestellten Zielpuffer. Die Datenelemente (<code>Data element #1</code> bis <code>#N</code>) werden ohne vorangestellte Record-Nummer oder zusätzliche Header direkt sequenziell ab Byte 0 in den Puffer kopiert. Ist der Record gültig, aber nicht gespeichert, bleibt der Puffer leer (Größe 0).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Diagramm gemäß SWS_Dem_00075 das exakte Pufferformat für die Übergabe an das Dcm: Der Puffer enthält ausschließlich die reinen Nutzdaten (<code>Data element #1..#N</code>) des angeforderten Datensatzes. Dies steht im normativen Gegensatz zu Funktionen wie <code>Dem_DcmGetSizeOfExtendedDataRecordByDTC</code> (SWS_Dem_00076), bei denen Headerinformationen (wie die Record-Nummer) mitgezählt werden. Entwickler müssen sicherstellen, dass der Puffer mindestens die Gesamtlänge der summierten Nutzdatenelemente aufnehmen kann.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1454ac5560939916", "to": "FIG-7a454033a5910788", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
